    y = observation.get('self_position', [0, 0])[1]
    w = observation.get('grid_width', 10)
    h = observation.get('grid_height', 10)
    obstacles = set(map(tuple, observation.get('obstacles', [])))
    resources = list(map(tuple, observation.get('resources', [])))
    opp_pos = observation.get('opponent_position', [])
    ox = opp_pos[0] if len(opp_pos) > 0 else None
    oy = opp_pos[1] if len(opp_pos) > 1 else None

    def safe(nx, ny):
        if 0 <= nx < w and 0 <= ny < h:
            return (nx, ny) not in obstacles
        return False

    def dist(a, b):
        return abs((a[0] if a else 0) - (b[0] if b else 0)) + abs((a[1] if a else 0) - (b[1] if b else 0))

    # Prioritize resource collection if resources are available
    resource_positions = resources
    if resource_positions:
