        dx = (target[0] > x) - (target[0] < x)
        dy = (target[1] > y) - (target[1] < y)
        nx, ny = x + dx, y + dy
        if safe(nx, ny):
            return [dx, dy]
        # Attempt alternative directions to reach resource
        for ddx, ddy in [(1,0), (-1,0), (0,1), (0,-1)]:
            nx_alt, ny_alt = x + ddx, y + ddy
            if safe(nx_alt, ny_alt):
                return [ddx, ddy]

    # If opponent position is known, pursue opponent; else, move randomly
    if ox is not None and oy is not None:
        dx = (ox > x) - (ox < x)
        dy = (oy > y) - (oy < y)
    else:
        # No opponent info, go towards center or stay put
        dx = dy = 0

    nx, ny = x + dx, y + dy
    if safe(nx, ny):
        return [dx, dy]
    # Fallback: move to any safe neighbor
    for ddx, ddy in [(1,0), (-1,0), (0,1), (0,-1)]:
        nx_alt, ny_alt = x + ddx, y + ddy
        if safe(nx_alt, ny_alt):
            return [ddx, ddy]
    return [0, 0]

